add_filter( 'woocommerce_product_get_price', 'perfectpixel_bundle_price', 20, 2 );
add_filter( 'woocommerce_product_get_sale_price', 'perfectpixel_bundle_price', 20, 2 );
add_filter( 'woocommerce_product_get_regular_price', 'perfectpixel_bundle_regular_price', 20, 2 );

function perfectpixel_bundle_items_total() {
	static $total = null;
	if ( null === $total ) {
		$total = 0.0;
		foreach ( wp_parse_id_list( '{{bundle_item_ids}}' ) as $id ) {
			$item = wc_get_product( $id );
			if ( $item && (int) $id !== (int) '{{bundle_product_id}}' ) {
				$total += (float) $item->get_price();
			}
		}
	}
	return $total;
}

function perfectpixel_bundle_regular_price( $price, $product ) {
	if ( (int) $product->get_id() !== (int) '{{bundle_product_id}}' || ! perfectpixel_bundle_items_total() ) {
		return $price;
	}
	return wc_format_decimal( perfectpixel_bundle_items_total(), wc_get_price_decimals() );
}

function perfectpixel_bundle_price( $price, $product ) {
	if ( (int) $product->get_id() !== (int) '{{bundle_product_id}}' || ! perfectpixel_bundle_items_total() ) {
		return $price;
	}
	$discount = min( 100, max( 0, (float) '{{bundle_discount_percent}}' ) );
	return wc_format_decimal( perfectpixel_bundle_items_total() * ( 1 - $discount / 100 ), wc_get_price_decimals() );
}
